import { SetMetadata } from '@nestjs/common';
import { SCOPE_OPTIONS_METADATA } from '@nestjs/common/constants.js';
import { PROCESSOR_METADATA, WORKER_METADATA } from '../bull.constants.js';
export function Processor(queueNameOrOptions, maybeWorkerOptions) {
    const options = queueNameOrOptions && typeof queueNameOrOptions === 'object'
        ? queueNameOrOptions
        : { name: queueNameOrOptions };
    return (target) => {
        SetMetadata(SCOPE_OPTIONS_METADATA, options)(target);
        SetMetadata(PROCESSOR_METADATA, options)(target);
        if (maybeWorkerOptions) {
            SetMetadata(WORKER_METADATA, maybeWorkerOptions)(target);
        }
    };
}
